		ret = disk_alloc_zone_resources(disk, pool_size);
		if (ret)
			kfree(args->zones_cond);
	}
```
```c
	disk_set_zones_cond_array(disk, args->zones_cond);
+	args->zones_cond = NULL;
```
```c
+	if (ret <= 0)
+		goto free_resources;
...
+	if (args.sector != capacity) {
		...
		ret = -ENODEV;
+		goto free_resources;
	}
...
+	ret = disk_update_zone_resources(disk, &args);
+	if (ret)
+		goto free_resources;
...
+free_resources:
	pr_warn("%s: failed to revalidate zones\n", disk->disk_name);
+	kfree(args.zones_cond);
```
Reason:  
The first change frees `zones_cond` inside `disk_revalidate_zone_resources()` if `disk_alloc_zone_resources()` fails. The second change sets `args->zones_cond = NULL` after the ownership is transferred to the disk, preventing a double free. The third change restructures `blk_revalidate_disk_zones()` with a `free_resources` label that frees `zones_cond` and other resources on all error paths (report_zones failure, capacity mismatch, or `disk_update_zone_resources()` failure), ensuring no memory leak.

