	struct gendisk *disk = args->disk;
	struct request_queue *q = disk->queue;
	sector_t capacity = get_capacity(disk);
	sector_t zone_sectors = q->limits.chunk_sectors;
	struct blk_zone_wplug *zwplug;
	unsigned long flags;
	unsigned int wp_offset;

